// Code generated by `cargo xtask generate` from proto/api.proto. DO NOT EDIT.

//! Every API method reaches its endpoint, its batch command and its async
//! consumer command, from the async and the blocking client (spec 15).

#![cfg(feature = "client")]
#![allow(clippy::unwrap_used, clippy::pedantic)] // tests: unwrap is the assertion

mod common;

use cent::*;
use common::{Fake, raw};

const METHODS: &[&str] = &[
    "publish",
    "broadcast",
    "subscribe",
    "unsubscribe",
    "disconnect",
    "presence",
    "presence_stats",
    "history",
    "history_remove",
    "info",
    "refresh",
    "channels",
    "connections",
    "update_user_status",
    "get_user_status",
    "delete_user_status",
    "block_user",
    "unblock_user",
    "revoke_token",
    "invalidate_user_tokens",
    "device_register",
    "device_update",
    "device_remove",
    "device_list",
    "device_topic_list",
    "device_topic_update",
    "user_topic_list",
    "user_topic_update",
    "send_push_notification",
    "update_push_status",
    "cancel_push",
    "map_publish",
    "map_remove",
    "map_read_state",
    "map_read_stream",
    "map_stats",
    "map_clear",
    "shared_poll_publish",
];

fn paths(fake: &Fake) -> Vec<String> {
    fake.requests().iter().map(|r| r.uri.clone()).collect()
}

fn endpoints() -> Vec<String> {
    METHODS
        .iter()
        .map(|m| format!("http://centrifugo.test/api/{m}"))
        .collect()
}

